    // ── how2guidess.com ────────────────────────────────────────────────────
    // how2guidess.com hides the destination behind two sequential button
    // clicks: first #gi (the "Get Link" initiator), then #ci (the actual
    // confirmation). This bypasser polls for each button in order, clicks
    // them with a 500 ms gap between steps, and reports progress via the
    // notification card.

    function runHow2GuidesBypasser() {
        const SITE = 'how2guidess.com';

        const waitAndClick = (id, afterMs, afterFn, nh) => {
            pollUntil(() => {
                    const el = document.getElementById(id);
                    if(!el) return false;
                    el.click();
                    return true;
                }, 200, 150)
                .then(() => {
                    if(afterFn) setTimeout(afterFn, afterMs);
                })
                .catch(() => {
                    nh.update(`${SITE}: #${id} not found — unsupported layout.`, 'error');
                    setTimeout(() => nh.remove(), 6000);
                });
        };

        const run = () => {
            const t = makeTimer();
            const nh = notify(`${SITE} — bypassing…`, 'loading', 0, {
                site: SITE
            });
            waitAndClick('gi', 500, () => {
                nh.update(`${SITE} — step 1 done, clicking confirm…`, 'loading', {
                    site: SITE
                });
                waitAndClick('ci', 0, () => {
                    nh.update(`${SITE} — done in ${t.elapsed()}s`, 'success', {
                        site: SITE,
                        time: t.elapsed() + 's'
                    });
                    setTimeout(() => nh.remove(), 2000);
                }, nh);
            }, nh);
        };
        onReady(run);
    }

    // ── link-unlock.com ────────────────────────────────────────────────────
    // link-unlock.com uses a two-call REST API to unlock links:
    //   1. GET  https://api.link-unlock.com/u/<slug>
    //      → returns unlock config including an array of step IDs.
    //   2. POST https://api.link-unlock.com/u/<slug>/complete  { steps: [...] }
    //      → returns { destinationUrl } when all steps are marked complete.
    // By passing all step IDs in the POST body at once we skip every
    // individual ad/social step the site would normally require.

    function runLinkUnlockBypasser() {
        const SITE = 'link-unlock.com';
        const t = makeTimer();
        const nh = notify(`${SITE} — bypassing…`, 'loading', 0, {
            site: SITE
        });
        const handleError = makeErrHandler(SITE, nh, 7000);

        const slug = new URL(location.href).pathname.split('/').filter(Boolean)[0];
        if(!slug) {
            handleError('could not read slug from URL', null);
            return;
        }

        (async () => {
            try {
                nh.update(`${SITE} — fetching steps…`, 'loading', {
                    site: SITE
                });
                const d1 = await fetchJSON(`https://api.link-unlock.com/u/${slug}`);
                const steps = d1?.unlock?.steps?.map(s => s.id);
                if(!steps?.length) throw new Error('No steps found in API response');

                nh.update(`${SITE} — completing steps…`, 'loading', {
                    site: SITE
                });
                const d2 = await fetchJSON(`https://api.link-unlock.com/u/${slug}/complete`, {
                    method: 'POST',
                    headers: {
                        'Content-Type': 'application/json'
                    },
                    body: JSON.stringify({
                        steps
                    }),
                });
                if(!d2?.destinationUrl) throw new Error('No destinationUrl in response');

                safeRedirect(d2.destinationUrl, nh, {
                    t,
                    siteLabel: SITE
                });
            } catch (err) {
                handleError('bypass failed', err);
            }
        })();
    }

