    //
    //   (other subdomains) — Uses a form-based flow: polls for either a
    //     direct href on #btn6, or a named form (name matches /^tp\d*$/i).
    //     On match: submits the form via submitForm() to trigger the server
    //     redirect to the real destination.

    function runTapVietCodeBypasser() {
        const SITE = 'tapvietcode.com';

        if(host.includes('blog.tapvietcode.com')) {
            const t = makeTimer();
            const nh = notify(`${SITE} — waiting for continue button…`, 'loading', 0, {
                site: SITE
            });

            const tryClick = () => {
                const btn = document.getElementById('continueBtn');
                if(!btn) return false;
                if(!btn.href) {
                    nh.update(`${SITE}: continueBtn has no href.`, 'error');
                    setTimeout(() => nh.remove(), 6000);
                    return true;
                }
                safeRedirect(btn.href, nh, {
                    t,
                    siteLabel: SITE
                });
                return true;
            };

            const init = () => {
                pollUntil(tryClick, 200, 150).catch(() => {
                    nh.update(`${SITE}: continue button not found — unsupported layout.`, 'error');
                    setTimeout(() => nh.remove(), 6000);
                });
            };
            onReady(init);

        } else {
            const t = makeTimer();
            const nh = notify(`${SITE} — reading destination from storage…`, 'loading', 0, {
                site: SITE
            });

            const tryStorage = () => {
                try {
                    for(let i = 0; i < localStorage.length; i++) {
                        const k = localStorage.key(i);
                        const v = localStorage.getItem(k);
                        if(!v?.includes('"lnk1"')) continue;
                        try {
                            const j = JSON.parse(v);
                            const u = j?.data?.lnk?.lnk1?.url || j?.lnk?.lnk1?.url;
                            if(u) {
                                safeRedirect(u, nh, {
                                    t,
                                    siteLabel: SITE
                                });
                                return true;
                            }
                        } catch (_) {}
                    }
                } catch (e) {
                    console.error('[ULB/tapvietcode] localStorage read failed', e);
                }
                return false;
            };

            const init = () => {
                pollUntil(tryStorage, 300, 100).catch(() => {
                    nh.update(`${SITE}: lnk1 URL not found in storage — unsupported layout.`, 'error');
                    setTimeout(() => nh.remove(), 6000);
                });
            };
            onReady(init);
        }
    }

    // ── gplinks.co ─────────────────────────────────────────────────────────
    // gplinks.co protects links with a Cloudflare Turnstile captcha embedded
    // inside an iframe. The sitekey is not in a data-sitekey attribute — it
    // is encoded in the iframe src path (e.g. /challenges.cloudflare.com/.../<key>/...).
    // This bypasser:
    //   1. Extracts the sitekey from the iframe src using a regex on the 20+
    //      character path segment, falling back to getSiteKey() if not found.
    //   2. Waits up to 5 s for app_vars to appear as a secondary sitekey source.
    //   3. Solves the Turnstile automatically via solveTurnstile().
    //   4. Injects the token into [name="cf-turnstile-response"] and submits
    //      the form, which the server validates before issuing the redirect.

    function runGpLinksBypasser() {
        const SITE = 'gplinks.co';
        const t = makeTimer();
        const nh = notify(`${SITE} — solving captcha…`, 'loading', 0, {
            site: SITE
        });
        const handleError = makeErrHandler(SITE, nh, 7000);

        const getGpSiteKey = () => {
            const iframe = document.querySelector('iframe[src*="challenges.cloudflare.com"]');
            if(iframe) {
                const m = iframe.getAttribute('src').match(/\/([0-9a-zA-Z_\-]{20,})\//);
                if(m) return m[1];
            }
            return getSiteKey();
        };

        const init = async () => {
            let btn;
            try {
                btn = await waitForEl('#captchaButton', 200, 15_000);
            } catch (e) {
                handleError('captchaButton not found', e);
                return;
            }

            const existingHref = btn.getAttribute('href');
            if(existingHref && existingHref !== '#' && !existingHref.startsWith('javascript')) {
                safeRedirect(existingHref, nh, {
                    t,
                    siteLabel: SITE
                });
                return;
            }

            const sitekey = getGpSiteKey();
            if(!sitekey) {
                handleError('could not find Turnstile sitekey', null);
                return;
            }

            let token;
            try {
                token = await solveTurnstile(sitekey);
            } catch (e) {
                handleError('Turnstile solve failed', e);
                return;
            }

            let tsInput = document.querySelector('[name="cf-turnstile-response"]');
            if(!tsInput) {
                tsInput = Object.assign(document.createElement('input'), {
                    type: 'hidden',
                    name: 'cf-turnstile-response'
                });
                document.body.appendChild(tsInput);
            }
            tsInput.value = token;

            const cbName = document.querySelector('[data-callback]')?.dataset?.callback;
            if(cbName) {
                try {
                    if(typeof _uw[cbName] === 'function') _uw[cbName](token);
                } catch (_) {}
            }

            nh.update(`${SITE} — waiting for link…`, 'loading', {
                site: SITE
            });
            pollUntil(() => {
                    const href = btn.getAttribute('href');
                    return href && href !== '#' && !href.startsWith('javascript') && href.startsWith('http') ? href : false;
                }, 200, 150)
                .then(href => safeRedirect(href, nh, {
                    t,
                    siteLabel: SITE
                }))
                .catch(() => handleError('link did not appear after captcha solve — unsupported layout', null));
        };

        onReady(init);
    }

    // ── powergam.online ────────────────────────────────────────────────────
    // powergam.online is a multi-step ad-locker that tracks progress through
    // cookies (imps, lid, pages, pid, step_count, vid) and requires the
    // browser to POST to each step endpoint in sequence. This bypasser:
    //   1. Reads the required cookies from document.cookie.
    //   2. Verifies all six required keys are present; if not, waits for the
    //      page to set them (polls via MutationObserver on document.cookie).
    //   3. Iterates through every step (1..pages), POSTing the step data with
    //      the correct Referer header to simulate a real page visit.
    //   4. Reads the finalURL from cookies after all steps complete and redirects.

    function runPowergamBypasser() {
        const SITE = host;
        const REQUIRED = ['imps', 'lid', 'pages', 'pid', 'step_count', 'vid'];
        const STEP_TIMEOUT_MS = 12000; // per-step POST timeout
        const COOKIE_WAIT_MS = 30000; // give up waiting for cookies after 30 s
        const t = makeTimer();

        // ── Safe cookie parser ─────────────────────────────────────────────
        // Handles values that contain '=' and ignores malformed entries.
        const getCookies = () => {
            const result = {};
            for(const c of document.cookie.split('; ')) {
                if(!c) continue;
                const i = c.indexOf('=');
                if(i < 0) continue;
                try {
                    result[decodeURIComponent(c.slice(0, i))] =
                        decodeURIComponent(c.slice(i + 1));
                } catch (_) {}
            }
            return result;
        };

        const handleError = makeErrHandler(SITE, null, 7000);

        const runSteps = async (cookies, pages, finalURL) => {
            const ref = window.location.origin;
            for(let s = 1; s <= pages; s++) {
                const nh2 = notify(`${SITE} — posting step ${s}/${pages}…`, 'loading', 0, {
                    site: SITE,
                    time: t.elapsed() + 's'
                });
                const body = new URLSearchParams({
                    ad_impressions: 2,
                    form_name: 'ads-track-data',
                    next_target: s === pages ? finalURL : ref,
                    step_id: String(s),
                    visitor_id: cookies.vid,
                });
                try {
                    await fetchWithTimeout(`${ref}/`, {
                        method: 'POST',
                        headers: {
                            'Content-Type': 'application/x-www-form-urlencoded',
                            Referer: `${ref}/`
                        },
                        credentials: 'include',
                        body: body.toString(),
                    }, STEP_TIMEOUT_MS);
                } catch (e) {
                    if(e.name === 'AbortError') {
                        console.warn(`[ULB/${SITE}] Step ${s}/${pages} timed out — continuing`);
                    } else {
                        console.warn(`[ULB/${SITE}] POST failed at step ${s}`, e);
                    }
                }
                nh2.remove();
                if(s < pages) await sleep(1200);
            }

            notify(`${SITE} — redirecting…`, 'success', 2000, {
                site: SITE,
                time: t.elapsed() + 's'
            });

            if(safeUrl(finalURL)) location.href = finalURL;
            else handleError('invalid final URL', null);
        };

        let executed = false;
        const waiter = setInterval(() => {
            if(executed) return;
            const cookies = getCookies();
            if(!REQUIRED.every(k => k in cookies)) return;
            executed = true;
            clearInterval(waiter);

            const pages = parseInt(cookies.pages, 10);
            if(!pages || pages < 1) {
                handleError('invalid pages cookie', null);
                return;
            }

            const finalURL = `https://gplinks.co/${cookies.lid}?pid=${cookies.pid}&vid=${cookies.vid}`;
            const delaySecs = pages * 30;

            // ── Nuke the page's own timers & block new ones ────────────────
            // 1. Kill all currently-registered timers.
            // 2. Override setTimeout/setInterval on the page's window so any
            //    new ones it tries to register are silently dropped.
            // We save the real functions first so our own code (showCountdown,
            // sleep, notify, etc.) still works via the saved references.
            const _realSetTimeout = _uw.setTimeout.bind(_uw);
            const _realSetInterval = _uw.setInterval.bind(_uw);
            const _realClearTimeout = _uw.clearTimeout.bind(_uw);
            const _realClearInterval = _uw.clearInterval.bind(_uw);

            // Kill everything running right now.
            let _nukeId = _realSetTimeout(() => {}, 0);
            while(_nukeId--) {
                _realClearTimeout(_nukeId);
                _realClearInterval(_nukeId);
            }

            // Freeze the page — any new timer it tries to set is a no-op.
            _uw.setTimeout = () => -1;
            _uw.setInterval = () => -1;

            // Replace the on-page countdown UI with our status text.
            const timerDiv = document.getElementById('myTimerDiv');
            if(timerDiv) {
                timerDiv.innerHTML = '<span>Bypassing GPlinks...</span>';
            }
            console.log(`[ULB/${SITE}] Gurtified`);

            notify(`${SITE} — ${pages} step${pages > 1 ? 's' : ''} detected, waiting ${delaySecs}s…`, 'info', 4000, {
                site: SITE
            });
            showCountdown(delaySecs, () => runSteps(cookies, pages, finalURL), `${SITE} — ${pages} page${pages > 1 ? 's' : ''}`);
        }, 500);

        // Safety net: if the required cookies never appear, stop polling and notify.
        setTimeout(() => {
            if(!executed) {
                clearInterval(waiter);
                handleError('required cookies not set after 30s — try refreshing the page', null);
            }
        }, COOKIE_WAIT_MS);
    }

