    // ── whatwhatboy.com/scoobyontop2.html ────────────────────────────────
    // Generates a key locally — no network request needed.
    // Algorithm (from original snippet):
    //   epoch = floor(Date.now() / 14400000)   ← 4-hour window
    //   salt  = XOR-decoded string from hardcoded byte array
    //   fnv1a = FNV-1a 32-bit hash of "<epoch>|<n>|<salt>"
    //   key   = "SCOOBY-FREE-" + base36_4(fnv1a(…|1|…)) + "-" + … + "-" + …
    // Fully client-side; result displayed via showKeyCard.

    function runScoobyontopBypasser() {
        const SITE = 'whatwhatboy.com';
        const t = makeTimer();

        const init = () => {
            try {
                // Decode salt via XOR with 90
                const ENC = [9, 57, 106, 106, 56, 35, 23, 105, 52, 47, 17, 105, 35, 104, 106, 104, 108, 123];
                const salt = ENC.map(c => String.fromCharCode(c ^ 90)).join('');

                // Current 4-hour epoch
                const epoch = Math.floor(Date.now() / 14_400_000);

                // FNV-1a 32-bit
                const fnv1a = str => {
                    let h = 2166136261;
                    for(let i = 0; i < str.length; i++) {
                        h ^= str.charCodeAt(i);
                        h = Math.imul(h, 16777619);
                    }
                    return h >>> 0;
                };

                // Base-36 encode, 4 chars wide
                const b36_4 = v => {
                    let r = '',
                        c = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789';
                    for(let i = 0; i < 4; i++) {
                        r += c[v % 36];
                        v = Math.floor(v / 36);
                    }
                    return r;
                };

                const key =
                    'SCOOBY-FREE-' +
                    b36_4(fnv1a(`${epoch}|1|${salt}`)) + '-' +
                    b36_4(fnv1a(`${epoch}|2|${salt}`)) + '-' +
                    b36_4(fnv1a(`${epoch}|3|${salt}`));

                showKeyCard(key, SITE, t, 30_000);
            } catch (err) {
                notify(`${SITE}: key generation failed — ${err.message}`, 'error', 8000, {
                    site: SITE
                });
            }
        };

        onReady(init);
    }

    // ── vayuhub.space/getkey ───────────────────────────────────────────────
    // vayuhub.space/getkey?hwid=<hwid> is a two-checkpoint HWID key system.
    // Flow per checkpoint n (1 then 2):
    //   1. GET  /api/checkpoint?hwid=<hwid>  (fires the checkpoint timer)
    //   2. Wait 15 s (simulates ad view time)
    //   3. GET  /api/callback                (signals completion to server)
    //   4. GET  /api/verify?hwid=<hwid>      → { step }
    //      If step >= n → checkpoint done; else retry the whole loop.
    //   After both checkpoints: reload so the site delivers the key.

    function runVayuHubBypasser() {
        const SITE = 'vayuhub.space';
        const hwid = new URLSearchParams(location.search).get('hwid');
        if(!hwid) return; // no hwid param — nothing to bypass

        const t = makeTimer();
        const nh = notify(`${SITE} — starting checkpoint flow…`, 'loading', 0, {
            site: SITE
        });
        const handleError = makeErrHandler(SITE, nh, 10000);

        // Set validation cookie the site expects
        document.cookie = `validating_hwid=${hwid};path=/;max-age=3600;SameSite=Lax`;

        const checkpointUrl = `https://vayuhub.space/api/checkpoint?hwid=${encodeURIComponent(hwid)}`;
        const callbackUrl = 'https://vayuhub.space/api/callback';
        const verifyUrl = `https://vayuhub.space/api/verify?hwid=${encodeURIComponent(hwid)}`;

        const safeFetch = (url, opts) =>
            fetch(url, {
                ...(opts || {}),
                redirect: 'manual'
            }).catch(() => null);

        const getStep = async () => {
            try {
                const r = await fetch(verifyUrl, {
                    redirect: 'follow'
                });
                const d = await r.json();
                return typeof d?.step === 'number' ? d.step : -1;
            } catch (_) {
                return -1;
            }
        };

        // Polls verify every 3 s until step >= target, then resolves
        const waitForStep = (target) => new Promise(resolve => {
            const iv = setInterval(async () => {
                const step = await getStep();
                if(step >= target) {
                    clearInterval(iv);
                    resolve();
                }
            }, 3000);
            // Hard cap: 90 s per checkpoint
            setTimeout(() => {
                clearInterval(iv);
                resolve();
            }, 90_000);
        });

        const runCheckpoint = async (n) => {
            nh.update(`${SITE} — checkpoint ${n}/2 — firing…`, 'loading', {
                site: SITE
            });
            await safeFetch(checkpointUrl, {
                method: 'GET'
            });

            nh.update(`${SITE} — checkpoint ${n}/2 — waiting 15 s…`, 'loading', {
                site: SITE
            });
            await sleep(15_000);

            await safeFetch(callbackUrl, {
                method: 'GET',
                redirect: 'follow'
            });

            nh.update(`${SITE} — checkpoint ${n}/2 — verifying…`, 'loading', {
                site: SITE
            });
            const step = await getStep();
            if(step >= n) return; // confirmed done

            // Server hasn't registered it yet — keep polling
            await waitForStep(n);
        };

        const run = async () => {
            try {
                for(let n = 1; n <= 2; n++) {
                    await runCheckpoint(n);
                    nh.update(`${SITE} — checkpoint ${n}/2 ✔`, 'loading', {
                        site: SITE
                    });
                    if(n < 2) await sleep(500);
                }

                nh.update(`${SITE} — done in ${t.elapsed()}s — reloading for key…`, 'loading', {
                    site: SITE
                });
                await sleep(600);
                nh.remove();
                location.reload();
            } catch (err) {
                handleError('bypass failed', err);
            }
        };

        onReady(run);
    }

    // ── socialwolvez.com/app/l/* ───────────────────────────────────────────
    // Next.js streams server data into self.__next_f (an array of strings).
    // The destination URL is embedded in that payload as "url":"<href>".
    // We poll until the array is populated, extract the first match, and
    // redirect — identical logic to the one-liner below, fully integrated:
    //   location.href=((self.__next_f||[]).join("").match(/"url":"(.*?)"/)||[])[1]

    function runSocialWolvezBypasser() {
        const SITE = 'socialwolvez.com';
        const t = makeTimer();
        const nh = notify(`${SITE} — reading Next.js payload…`, 'loading', 0, {
            site: SITE
        });
        const handleError = makeErrHandler(SITE, nh, 7000);

        const tryExtract = () => {
            const raw = (_uw.self.__next_f || []).join('');
            if(!raw) return false;
            const m = raw.match(/"url":"(.*?)"/);
            // Unescape any Unicode escape sequences Next.js may encode (e.g. \u002F → /)
            const url = m && m[1] ? m[1].replace(/\\u([\dA-Fa-f]{4})/g, (_, h) => String.fromCharCode(parseInt(h, 16))) : null;
            if(url && safeUrl(url)) {
                safeRedirect(url, nh, {
                    t,
                    siteLabel: SITE
                });
                return true;
            }
            return false;
        };

        const init = () => {
            if(tryExtract()) return;
            pollUntil(tryExtract, 150, 100).catch(() => {
                handleError('"url" key not found in Next.js payload (__next_f)', null);
            });
        };

        onReady(init);
    }

